CREATE OR REPLACE VIEW lr_serverless_aws_us_catalog.bricksurance_semantics.accumulation_metrics
COMMENT 'Catastrophe accumulation KPIs over event losses - gross loss, ceded recovery and net retained by event and peril. The exposure view reinsurance and capital teams work from, derived from the event-loss records rather than stored. Amounts are in original currency; group by or filter on currency_code before summing money. Query measures with MEASURE(name).'
WITH METRICS
LANGUAGE YAML
AS $$
version: 0.1

source: lr_serverless_aws_us_catalog.bricksurance_reinsurance.event_loss

joins:
  - name: cat_event
    source: lr_serverless_aws_us_catalog.bricksurance_reinsurance.cat_event
    on: source.cat_event_id = cat_event.cat_event_id

dimensions:
  - name: event_name
    expr: cat_event.event_name
  - name: peril_code
    expr: cat_event.cause_of_loss_code
  - name: currency_code
    expr: currency_code

measures:
  - name: event_count
    expr: COUNT(DISTINCT source.cat_event_id)
  - name: gross_loss_total
    expr: SUM(gross_loss_amount)
  - name: ceded_recovery_total
    expr: SUM(ceded_loss_amount)
  - name: net_retained_total
    expr: SUM(gross_loss_amount - ceded_loss_amount)
$$;
